import java.util.*;
import java.io.*;

public class Main {
    static boolean isLucky(long x){
        if(x<=0) return false;
        while(x>0){
            long d=x%10;
            if(d!=4&&d!=7) return false;
            x/=10;
        }
        return true;
    }
    public static void main(String[] args) throws IOException{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        long n=Long.parseLong(st.nextToken());
        long k=Long.parseLong(st.nextToken());
        long[] fact=new long[21];
        fact[0]=1;
        for(int i=1;i<=20;i++) fact[i]=fact[i-1]*i;
        int m=0;
        while(m<n && m<20 && fact[m]<k) m++;
        if(fact[m]<k){
            System.out.println(-1);
            return;
        }
        long base=n-m;
        // count lucky numbers <= base
        int count=0;
        ArrayDeque<Long> queue=new ArrayDeque<>();
        queue.add(4L); queue.add(7L);
        while(!queue.isEmpty()){
            long cur=queue.poll();
            if(cur<=base) count++;
            if(cur<=1000000000L){
                queue.add(cur*10+4);
                queue.add(cur*10+7);
            }
        }
        // k-th permutation (1-indexed) of base+1..n
        long idx=k-1;
        List<Long> elems=new ArrayList<>();
        for(long i=base+1;i<=n;i++) elems.add(i);
        long[] perm=new long[m];
        for(int i=0;i<m;i++){
            long f=fact[m-1-i];
            int p=(int)(idx/f);
            idx%=f;
            perm[i]=elems.get(p);
            elems.remove(p);
        }
        for(int j=0;j<m;j++){
            long pos=base+1+j;
            if(isLucky(pos)&&isLucky(perm[j])) count++;
        }
        System.out.println(count);
    }
}
